// TH18 v1.00a st01bs Boss2, local source 0 = card frame 124.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;
const TH18_RICE: int = 480;
xformdef MOTION(gain: fx, turn_angle: angle, angular: angle) {
    @30 step_speed(0fx, 30);
    turn(turn_angle);
    set_ang_vel(angular);
    @100 set_accel(gain);
    set_accel(0fx);
    set_ang_vel(0deg);
}
sub group(a: angle, turn_angle: angle, angular: angle, n: int, inc: fx, until: int) {
    for i in 0..7 {
        if $frame >= until { return; }
        var color: int = 2;
        if i == 0 { color = 4; }
        if i == 1 { color = 6; }
        if i == 2 { color = 8; }
        if i == 3 { color = 11; }
        if i == 4 { color = 13; }
        if i == 5 { color = 14; }
        sh_reset(0);
        sh_sprite(0, TH18_RICE, color);
        sh_ring(0, 1);
        sh_count(0, n, 1);
        sh_angle(0, a+((i*1820) as angle), 0deg);
        sh_speed(0, 2.5fx, 0fx);
        sh_dist(0, -10fx);
        sh_xform(0, MOTION((1.2fx+(i as fx)*inc)/100, turn_angle, angular));
        sh_fire(0);
        if i < 6 { card_wait(3); }
    }
}
async sub pattern() {
    wait(120);
    var until: int = $frame+SOURCE_LIMIT;
    set_self_int(1, until);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    var rank: int = global(GVAR_RANK);
    var n: int = 8;
    var inc: fx = 0.2fx;
    var pause: int = 180;
    if rank == 1 { n = 16; }
    if rank == 2 { n = 20; inc = 0.24fx; pause = 100; }
    if rank == 3 { n = 28; inc = 0.28fx; pause = 100; }
    wait(180);
    loop {
        if $frame >= until { return; }
        group(90deg, 60deg, 237 as angle, n, inc, until);
        if $frame >= until { return; }
        group(aim_player(), -60deg, -237 as angle, n, inc, until);
        if $frame >= until { return; }
        card_move_rand();
        card_wait(pause);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard2 only. int slot0=next-step count, int1=source end card-frame; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
